    out = [row[:] for row in grid]
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if divider is None:
        return out

    sources = [(r, c) for r in range(divider) for c, v in enumerate(grid[r]) if v == 4]
    for r, c in sources:
        out[r][c] = 0
        nr = r + 1
        if nr < divider:
            if nr == divider - 1 and c in (0, len(grid[0]) - 1):
                # At the outer edge, the impact is absorbed.
                continue
            out[nr][c] = 4
            if nr == divider - 1:
                k = 1
                while nr - k >= 0:
                    for nc in (c - k, c + k):
                        if 0 <= nc < len(grid[0]):
                            out[nr - k][nc] = 4
                    k += 1
    return out

